import{_ as r,l as c,o as e,c as i,v as l,p as m,x as o,d as s,i as n,S as d}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"malloc 实现","description":"","frontmatter":{"title":"malloc 实现","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/malloc-implementation.md","filePath":"cs/malloc-implementation.md","lastUpdated":1789023840000}'),p={name:"cs/malloc-implementation.md"};function h(f,a,_,b,u,T){const t=c("Mermaid");return e(),i("div",null,[a[1]||(a[1]=l('<h1 id="malloc-实现" tabindex="-1">malloc 实现 <a class="header-anchor" href="#malloc-实现" aria-label="Permalink to &quot;malloc 实现&quot;">​</a></h1><div class="epigraph"><p>malloc 在用户态把 mmap/brk 来的页切成块：空闲链表或分大小的 bin，释放合并，再不够才向内核要。</p><footer>—— 据 Wilson et al. 对动态存储分配的综述；ptmalloc/glibc 文档；McKusick 对用户堆的背景</footer></div><p><a href="/cs/memory-tagging">MTE</a> 假定分配器配合。<a href="/cs/buddy-allocator">buddy</a> 是内核页。<a href="/cs/memcg">memcg</a> 看的是页。缺口是 <strong>进程堆</strong>：glibc malloc 一类，如何少 brk、如何对多线程。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每次 <code>mmap</code> 4K 太粗、系统调用太贵。分配器：按 size class 把块串起来，大块单独 mmap。缺口：碎片（内外）、brk 收缩、与 fork 后锁（atfork）；double-free 检测是调试器，不是 POSIX。本课不把每个 bin 的阈值背下来。</p><p><span class="marginnote"><code>malloc_trim</code> 把顶空闲还内核。对齐与 <code>posix_memalign</code> 服务 SIMD/DMA 用户缓冲。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>小分配：从 tcache/fastbin 弹。耗尽：从 arena 的 bin 切，或 <code>mmap</code>。free：进 tcache，满则合并进 unsorted。对照 <a href="/cs/slab-allocator">slab</a>：内核按对象类型；malloc 按字节大小。对照 <a href="/cs/tmpfs">tmpfs</a>：堆是匿名页，不是文件。对照 <a href="/cs/direct-io">O_DIRECT</a>：对齐缓冲常来自 memalign。</p>',8)),(e(),m(d,null,{default:o(()=>[n(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22malloc%22%5D%20--%3E%20T%5B%22per-thread%20%E7%BC%93%E5%AD%98%22%5D%0A%20%20T%20--%3E%7C%22%E7%A9%BA%22%7C%20BIN%5B%22arena%20bins%22%5D%0A%20%20BIN%20--%3E%7C%22%E7%A9%BA%22%7C%20KERN%5B%22brk%20%E6%88%96%20mmap%22%5D%0A%20%20F%5B%22free%22%5D%20--%3E%20T%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>用户分配器把内核页变成任意字节对象，是几乎所有应用的底座。错误的分配器造成锁争用或碎片，看起来像泄漏。不要写成量化风控额度。与 KSM：堆页内容相同才可能被合，通常不合。</p><p>安全：未初始化、UAF 是分配器与类型系统共同的问题；MTE/ASan 在此挂钩。</p><p>实现上：tcache 使 free 的块不立刻合并，RSS 不下降是预期。fork 后子进程继承 arena 锁状态，不用 atfork 会死锁。可调试分配器把红区放进真实 malloc，和 ASan 叠要小心。 读法上只引用<a href="/cs/memory-tagging">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「内存进阶 / 回收、迁移与加固」课序里，对象是 <strong>malloc 实现</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入垃圾回收语言运行时——那是语言课。不保证嵌入式无 mmap 的 sbrk 独苗。下一课多线程竞技场：jemalloc/tcmalloc。</p><p>版本字段会变，课序钉的是机制对象「malloc 实现」，不是某一主线内核的结构体名。 后课默认：进程堆由用户分配器切页。多 arena 减少锁，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>malloc 用 bin 与可选 tcache 切内核页。</li><li>大块常独立 mmap；小块合并还 brk。</li><li>竞技场分配器是下一课。</li><li>出处：Wilson 综述；glibc malloc；<em>OSTEP</em> 用户内存。</li></ul>',11))])}const A=r(p,[["render",h]]);export{k as __pageData,A as default};
